import type { ToolId } from "./answers";

export const TEMPLATE_VERSION = "2026.11";

/** One line of a generated file, paired with its plain-English explanation. */
export type Line = { text: string; why?: string; risk?: boolean };

export type FileScope = "project" | "local";

export type GeneratedFile = {
  path: string;
  tools: ToolId[];
  scope: FileScope;
  purpose: string;
  lines: Line[];
};

export const line = (text: string, why?: string, risk?: boolean): Line => ({ text, why, risk });
export const blank = (): Line => ({ text: "" });

export function fileContent(file: GeneratedFile): string {
  return file.lines.map((l) => l.text).join("\n").trimEnd() + "\n";
}

export type JsonItem = { value: string; why: string; risk?: boolean };

/** JSON array rendered one item per line so each entry can carry its own explanation. */
export function jsonArray(indent: string, key: string, items: JsonItem[], why: string, trailingComma: boolean): Line[] {
  const comma = trailingComma ? "," : "";
  if (items.length === 0) return [line(`${indent}"${key}": []${comma}`, why)];
  return [
    line(`${indent}"${key}": [`, why),
    ...items.map((item, i) =>
      line(`${indent}  ${JSON.stringify(item.value)}${i < items.length - 1 ? "," : ""}`, item.why, item.risk),
    ),
    line(`${indent}]${comma}`),
  ];
}

export function versionComment(): Line {
  return line(
    `<!-- Generated by Ensemble Setup Studio, templates v${TEMPLATE_VERSION}. Edit freely. -->`,
    "Marks which template version made this file, so you know what to compare against if formats change.",
  );
}

/** Quotes a YAML value only when it needs it (colons, hashes, leading symbols). */
export function yamlString(value: string): string {
  return /: |#|^[[\]{}&*!|>'"%@`-]/.test(value) ? JSON.stringify(value) : value;
}
